import {GAME} from './model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function api(path,body){const response=await fetch('/api/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Matchroom-Request':'1'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed.');return result;}
export function mountSync(onLoad){
 const shell=document.createElement('section');shell.className='panel sync-panel';shell.innerHTML=`<div class="section-title"><h2>Spiideo connection</h2><span id="connection-state">Checking connection…</span></div><p id="sync-progress" role="status"></p><p id="connection-details" class="caption"></p><div class="toolbar"><label>Saved match<select id="saved-match"><option value="">Choose a synced match</option></select></label><button id="sync-current">Sync this match</button><button id="show-sync">Connection & scheduling</button></div><div id="sync-settings" hidden><div class="import-grid"><div><h3>Connect your signed-in session</h3><p>Sign in to Spiideo normally. In Developer Tools → Network, select a successful tags request, then Copy → Copy as cURL (bash). Paste it here, not in chat.</p><label>Copied request or Authorization value<textarea id="credential" rows="4" autocomplete="off" spellcheck="false" placeholder="Paste your successful request here"></textarea></label><p class="caption">Custom application headers and authentication headers are preserved. Connect tests the exact copied request. The command is never executed. Credentials stay in server memory and are cleared on restart. Session expiry requires reconnecting.</p><button id="connect">Connect</button> <button id="disconnect">Disconnect</button></div><div><h3>Track matches</h3><label>Game IDs, one per line<textarea id="game-ids" rows="3">${GAME}</textarea></label><label>Recheck interval<select id="interval">${[1,3,6,12,24].map(h=>`<option value="${h}" ${h===6?'selected':''}>Every ${h} hour${h===1?'':'s'}</option>`).join('')}</select></label><label class="inline"><input id="schedule" type="checkbox"> Enable scheduled syncing while this server runs</label><details><summary>Discover new games automatically</summary><p>Paste the Spiideo API URL that lists games from your recordings or competition view. The endpoint must return a content array. A game ID alone cannot discover other matches.</p><label>Game-list request URL<input id="discovery" placeholder="https://api.spiideo.net/v2/…"></label><label>Field containing the game ID<select id="id-field"><option value="id">id — game records</option><option value="gameId">gameId — records referencing games</option></select></label></details><button id="save-sync">Save settings</button> <button id="sync-all">Sync tracked games</button></div></div></div>`;
 document.querySelector('nav').before(shell);
 const $=s=>shell.querySelector(s);let initialized=false,lastRun=null,current=GAME,busy=false,loadedAt=null;
 try{current=localStorage.getItem('d3-selected-match')||GAME;}catch{}
 const fail=e=>{$('#sync-progress').textContent=e.message;};
 function state(s){busy=s.running;$('#connection-state').textContent=s.connected?(s.needsAttention?'Access needs attention':s.connectionInfo?.verified?'Request verified':'Session loaded'):'Not connected';$('#sync-progress').textContent=s.lastError||s.progress;$('#connection-details').textContent=s.connectionInfo?`Copied endpoint: ${s.connectionInfo.sourcePath||'not supplied'} · Headers retained: ${s.connectionInfo.headerNames.join(', ')}`:'';for(const id of ['#sync-current','#sync-all','#connect','#disconnect','#save-sync'])$(id).disabled=s.running; if(!initialized){const c=s.config;$('#game-ids').value=c.gameIds.length?c.gameIds.join('\n'):GAME;$('#interval').value=c.intervalHours;$('#schedule').checked=c.enabled;$('#discovery').value=c.discoveryUrl;$('#id-field').value=c.idField;initialized=true;}}
 async function load(id){const m=await api('matches/'+id);onLoad(m);current=id;loadedAt=m.importedAt;try{localStorage.setItem('d3-selected-match',id);}catch{}$('#saved-match').value=id;}
 async function refreshMatches(auto=false){const rows=await api('matches');$('#saved-match').innerHTML='<option value="">Choose a synced match</option>'+rows.map(m=>`<option value="${esc(m.gameId)}">${esc(m.contenders.map(c=>c.shortName||c.teamName).join(' vs '))} · ${esc(new Date(m.importedAt).toLocaleString())}</option>`).join('');if(rows.some(m=>m.gameId===current)){$('#saved-match').value=current;if(auto&&rows.find(m=>m.gameId===current).importedAt!==loadedAt)await load(current);}}
 $('#show-sync').onclick=()=>{$('#sync-settings').hidden=!$('#sync-settings').hidden;};
 $('#connect').onclick=async()=>{try{const credential=$('#credential').value;$('#credential').value='';const result=await api('connect',{credential});state(result);if(result.connectionInfo?.sourceGameId){current=result.connectionInfo.sourceGameId;$('#sync-current').textContent='Sync connected match';}}catch(e){fail(e);}};
 $('#disconnect').onclick=async()=>{try{state(await api('disconnect',{}));}catch(e){fail(e);}};
 $('#save-sync').onclick=async()=>{try{state(await api('settings',{gameIds:$('#game-ids').value,intervalHours:Number($('#interval').value),enabled:$('#schedule').checked,discoveryUrl:$('#discovery').value,idField:$('#id-field').value}));$('#sync-progress').textContent='Settings saved. Scheduled runs require this server and a valid session.';}catch(e){fail(e);}};
 $('#sync-current').onclick=async()=>{try{state(await api('sync',{gameId:current}));}catch(e){fail(e);}};
 $('#sync-all').onclick=async()=>{try{state(await api('sync',{}));}catch(e){fail(e);}};
 $('#saved-match').onchange=async e=>{if(e.target.value)try{await load(e.target.value);}catch(err){fail(err);}};
 async function poll(){try{const s=await api('status');state(s);if(lastRun!==s.lastRun){lastRun=s.lastRun;await refreshMatches(true);}}catch(e){fail(e);}}
 api('status').then(async s=>{state(s);lastRun=s.lastRun;await refreshMatches(true);}).catch(fail);
 setInterval(poll,2500);
}
